-- Avatar from a photo, generated by the server (Settings -> Character).
-- Frames live on disk (app.avatar.storage-dir/<user>/<avatar>/); this row tracks the job.
-- avatar_assets and generation_jobs from V2 stay unused: the frame set is fixed, so a file per
-- frame name is enough, and progress is two counters on the avatar.

ALTER TABLE avatars DROP CONSTRAINT avatars_status_check;
ALTER TABLE avatars ADD CONSTRAINT avatars_status_check
    CHECK (status IN ('GENERATING', 'REVIEW', 'ACTIVE', 'FAILED'));

ALTER TABLE avatars
    ADD COLUMN step           VARCHAR(16) NOT NULL DEFAULT 'MASTER' CHECK (step IN ('MASTER', 'FRAMES')),
    ADD COLUMN progress_done  INT         NOT NULL DEFAULT 0,
    ADD COLUMN progress_total INT         NOT NULL DEFAULT 0,
    ADD COLUMN error          TEXT,
    ADD COLUMN updated_at     TIMESTAMPTZ NOT NULL DEFAULT now();

-- At most one avatar in the making per user (next to the one active avatar).
CREATE UNIQUE INDEX uq_avatars_one_draft ON avatars (user_id) WHERE status <> 'ACTIVE';
